//! How many terminal columns text takes. The tables come from the Unicode data files
//! (`width_table.zig`, generated by `tools/gen-width.py`); this file searches them and splits
//! text into the clusters a terminal draws in one cell.
const std = @import("std");
const table = @import("width_table.zig");

const unicode = std.unicode;

pub const unicode_version = table.unicode_version;

/// 0 for combining marks, format characters (ZWJ, variation selectors) and controls, 2 for
/// East Asian Wide/Fullwidth and emoji-presentation characters, else 1.
pub fn codepointWidth(cp: u21) u2 {
    if (cp < 0x7f) return if (cp < 0x20) 0 else 1;
    if (inTable(&table.zero_width, cp)) return 0;
    if (inTable(&table.wide, cp)) return 2;
    return 1;
}

/// An emoji drawn one column wide by default, and two with VS16 after it.
pub fn isTextEmoji(cp: u21) bool {
    return inTable(&table.text_emoji, cp);
}

fn inTable(ranges: []const table.Range, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const r = ranges[mid];
        if (cp < r.lo) {
            hi = mid;
        } else if (cp > r.hi) {
            lo = mid + 1;
        } else return true;
    }
    return false;
}

const zwj: u21 = 0x200D;
const vs15: u21 = 0xFE0E;
const vs16: u21 = 0xFE0F;

fn isEmojiModifier(cp: u21) bool {
    return cp >= 0x1F3FB and cp <= 0x1F3FF;
}

fn isRegionalIndicator(cp: u21) bool {
    return cp >= 0x1F1E6 and cp <= 0x1F1FF;
}

fn isControl(cp: u21) bool {
    return cp < 0x20 or (cp >= 0x7f and cp < 0xa0);
}

pub const Cluster = struct {
    bytes: []const u8,
    width: u2,
    kind: Kind,

    pub const Kind = enum {
        /// Drawable text. Width 0 means a combining mark with no base before it.
        text,
        /// A C0/C1 control character or DEL: never draw it.
        control,
        /// A byte that is not valid UTF-8: draw U+FFFD instead.
        invalid,
    };
};

/// Splits text into clusters drawn in one cell: a base character plus the combining marks,
/// variation selectors, emoji modifiers and ZWJ-joined characters after it, and regional
/// indicator pairs (flags). This is an approximation of UAX #29 that covers what terminals
/// draw as one glyph.
pub const Iterator = struct {
    text: []const u8,
    i: usize = 0,

    pub fn init(text: []const u8) Iterator {
        return .{ .text = text };
    }

    pub fn next(it: *Iterator) ?Cluster {
        if (it.i >= it.text.len) return null;
        const start = it.i;
        const first = it.decode() orelse {
            it.i += 1;
            return .{ .bytes = it.text[start..it.i], .width = 1, .kind = .invalid };
        };
        it.i += first.len;
        if (isControl(first.cp)) return .{ .bytes = it.text[start..it.i], .width = 0, .kind = .control };

        var w: u2 = codepointWidth(first.cp);
        const base_text_emoji = isTextEmoji(first.cp);
        var join_next = false;
        var flag_open = isRegionalIndicator(first.cp);
        while (it.decode()) |d| {
            const cp = d.cp;
            if (isControl(cp)) break;
            if (join_next) {
                join_next = false;
            } else if (flag_open and isRegionalIndicator(cp)) {
                flag_open = false;
            } else if (cp == zwj) {
                join_next = true;
            } else if (cp == vs16) {
                if (base_text_emoji) w = 2;
            } else if (cp == vs15) {
                // Text presentation: leave the width as the base has it.
            } else if (isEmojiModifier(cp)) {
                // Skin tones join the emoji before them.
            } else if (codepointWidth(cp) != 0) break;
            it.i += d.len;
        }
        return .{ .bytes = it.text[start..it.i], .width = w, .kind = .text };
    }

    const Decoded = struct { cp: u21, len: u3 };

    fn decode(it: *const Iterator) ?Decoded {
        if (it.i >= it.text.len) return null;
        const rest = it.text[it.i..];
        const len = unicode.utf8ByteSequenceLength(rest[0]) catch return null;
        if (len > rest.len) return null;
        const cp = unicode.utf8Decode(rest[0..len]) catch return null;
        return .{ .cp = cp, .len = len };
    }
};

/// Columns `text` takes when drawn: controls take none, invalid bytes one each (as U+FFFD).
pub fn textWidth(text: []const u8) usize {
    var it: Iterator = .init(text);
    var n: usize = 0;
    while (it.next()) |c| n += c.width;
    return n;
}

test "codepointWidth: ASCII, controls, combining, wide, emoji" {
    try std.testing.expectEqual(1, codepointWidth('a'));
    try std.testing.expectEqual(1, codepointWidth(' '));
    try std.testing.expectEqual(0, codepointWidth(0x07));
    try std.testing.expectEqual(0, codepointWidth(0x7f));
    try std.testing.expectEqual(0, codepointWidth(0x9b));
    try std.testing.expectEqual(1, codepointWidth(0xe9)); // é
    try std.testing.expectEqual(1, codepointWidth(0xad)); // soft hyphen
    try std.testing.expectEqual(0, codepointWidth(0x0301)); // combining acute
    try std.testing.expectEqual(0, codepointWidth(0x20DD)); // enclosing circle (Me)
    try std.testing.expectEqual(0, codepointWidth(zwj));
    try std.testing.expectEqual(0, codepointWidth(vs16));
    try std.testing.expectEqual(0, codepointWidth(0xE0100)); // VS17
    try std.testing.expectEqual(0, codepointWidth(0x3099)); // wide but combining
    try std.testing.expectEqual(0, codepointWidth(0x1160)); // Hangul jamo vowel
    try std.testing.expectEqual(2, codepointWidth(0x4E2D)); // 中
    try std.testing.expectEqual(2, codepointWidth(0xAC00)); // 가
    try std.testing.expectEqual(2, codepointWidth(0xFF21)); // fullwidth A
    try std.testing.expectEqual(2, codepointWidth(0x3000)); // ideographic space
    try std.testing.expectEqual(2, codepointWidth(0x20000));
    try std.testing.expectEqual(2, codepointWidth(0x1F600)); // 😀
    try std.testing.expectEqual(2, codepointWidth(0x1F3B5)); // 🎵
    try std.testing.expectEqual(2, codepointWidth(0x1F1E9)); // regional indicator D
    try std.testing.expectEqual(1, codepointWidth(0x2764)); // ❤ (text by default)
    try std.testing.expectEqual(1, codepointWidth(0x2026)); // …
    try std.testing.expectEqual(1, codepointWidth(0x2580)); // ▀
    try std.testing.expectEqual(1, codepointWidth(0x10EEEE)); // kitty placeholder
    try std.testing.expectEqual(1, codepointWidth(0x10FFFF));
    try std.testing.expect(isTextEmoji(0x2764));
    try std.testing.expect(!isTextEmoji(0x1F600));
    try std.testing.expect(!isTextEmoji('a'));
}

test "the tables are sorted and do not overlap" {
    for ([_][]const table.Range{ &table.zero_width, &table.wide, &table.text_emoji }) |ranges| {
        for (ranges, 0..) |r, i| {
            try std.testing.expect(r.lo <= r.hi);
            if (i > 0) try std.testing.expect(ranges[i - 1].hi < r.lo);
        }
    }
}

fn expectClusters(text: []const u8, expected: []const struct { []const u8, u2 }) !void {
    var it: Iterator = .init(text);
    for (expected) |e| {
        const c = it.next() orelse return error.TooFewClusters;
        try std.testing.expectEqualStrings(e[0], c.bytes);
        try std.testing.expectEqual(e[1], c.width);
    }
    try std.testing.expectEqual(null, it.next());
}

test "Iterator: combining marks, ZWJ sequences, flags, VS16, skin tones" {
    try expectClusters("ab", &.{ .{ "a", 1 }, .{ "b", 1 } });
    try expectClusters("e\u{301}x", &.{ .{ "e\u{301}", 1 }, .{ "x", 1 } });
    try expectClusters("中文", &.{ .{ "中", 2 }, .{ "文", 2 } });
    // Family: man ZWJ woman ZWJ girl.
    try expectClusters("\u{1F468}\u{200D}\u{1F469}\u{200D}\u{1F467}!", &.{ .{ "\u{1F468}\u{200D}\u{1F469}\u{200D}\u{1F467}", 2 }, .{ "!", 1 } });
    // Flags pair up; a third indicator starts a new flag.
    try expectClusters("\u{1F1E9}\u{1F1EA}\u{1F1EB}", &.{ .{ "\u{1F1E9}\u{1F1EA}", 2 }, .{ "\u{1F1EB}", 2 } });
    try expectClusters("\u{2764}\u{FE0F}", &.{.{ "\u{2764}\u{FE0F}", 2 }});
    try expectClusters("\u{2764}", &.{.{ "\u{2764}", 1 }});
    try expectClusters("\u{2764}\u{FE0E}", &.{.{ "\u{2764}\u{FE0E}", 1 }});
    try expectClusters("\u{1F44D}\u{1F3FD}", &.{.{ "\u{1F44D}\u{1F3FD}", 2 }});
    // Keycap: digit, VS16, enclosing keycap.
    try expectClusters("1\u{FE0F}\u{20E3}", &.{.{ "1\u{FE0F}\u{20E3}", 2 }});
    // Kitty placeholder with row and column diacritics is one narrow cell.
    try expectClusters("\u{10EEEE}\u{305}\u{30D}\u{10EEEE}", &.{ .{ "\u{10EEEE}\u{305}\u{30D}", 1 }, .{ "\u{10EEEE}", 1 } });
    // A mark with no base is its own zero-width cluster.
    try expectClusters("\u{301}a", &.{ .{ "\u{301}", 0 }, .{ "a", 1 } });
    // Hangul jamo L+V+T joins into one wide cell.
    try expectClusters("\u{1100}\u{1161}\u{11A8}", &.{.{ "\u{1100}\u{1161}\u{11A8}", 2 }});
}

test "Iterator: controls and invalid UTF-8" {
    var it: Iterator = .init("a\tb\xffc\xe4\xb8");
    try std.testing.expectEqualStrings("a", it.next().?.bytes);
    const tab = it.next().?;
    try std.testing.expectEqual(.control, tab.kind);
    try std.testing.expectEqual(0, tab.width);
    try std.testing.expectEqualStrings("b", it.next().?.bytes);
    const bad = it.next().?;
    try std.testing.expectEqual(.invalid, bad.kind);
    try std.testing.expectEqual(1, bad.width);
    try std.testing.expectEqualStrings("c", it.next().?.bytes);
    // A truncated sequence is invalid byte by byte.
    try std.testing.expectEqual(.invalid, it.next().?.kind);
    try std.testing.expectEqual(.invalid, it.next().?.kind);
    try std.testing.expectEqual(null, it.next());
    // A control ends a cluster: the mark after it starts a new one.
    try expectClusters("e\n\u{301}", &.{ .{ "e", 1 }, .{ "\n", 0 }, .{ "\u{301}", 0 } });
}

test textWidth {
    try std.testing.expectEqual(0, textWidth(""));
    try std.testing.expectEqual(5, textWidth("hello"));
    try std.testing.expectEqual(4, textWidth("中文"));
    try std.testing.expectEqual(7, textWidth("Beyonc\u{e9}"));
    try std.testing.expectEqual(7, textWidth("Beyonce\u{301}"));
    try std.testing.expectEqual(3, textWidth("a\u{1F3B5}"));
    try std.testing.expectEqual(1, textWidth("a\x1b"));
}
